const fs=require('fs');
const puppeteer=require('puppeteer-core');
const PRODUCT='83567c124d171bf5d3664b41d8547555a2d196a8';
const base='http://127.0.0.1:8000/';
const routes=['index.html','corporate.html','energy.html','products.html','product.html','urea-46.html','caustic-soda-solid.html','sodium-sulphate-anhydrous.html','sales.html','technology.html','evidence-axis.html','ventures.html','contact.html','privacy.html','legal.html','404.html'];
const businessRoutes=new Set(['index.html','corporate.html','energy.html','products.html','sales.html','technology.html','evidence-axis.html','ventures.html','contact.html','urea-46.html','caustic-soda-solid.html','sodium-sulphate-anhydrous.html']);
const vps=[{name:'1920x1080',width:1920,height:1080},{name:'1440x900',width:1440,height:900},{name:'768x1024',width:768,height:1024},{name:'390x844',width:390,height:844},{name:'360x800',width:360,height:800}];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const out={productSha:PRODUCT,cases:{},failures:[],summary:{cases:0,horizontalOverflow:0,brokenImages:0,consoleErrors:0,pageErrors:0,requestFailures:0,missingShell:0,brokenInternalLinks:0,missingFragments:0,missingActions:0,legalNameRegression:0}};
function localAudit(source,anchors){const broken=[],fragments=[];for(const a of anchors){try{const u=new URL(a.href,base+source);if(u.origin!==new URL(base).origin)continue;let rel=decodeURIComponent(u.pathname.replace(/^\//,''))||'index.html';if(rel.endsWith('/'))rel+='index.html';rel=rel.split('?')[0];if(!fs.existsSync(rel)){broken.push({href:a.raw,resolved:rel});continue}if(u.hash){const id=decodeURIComponent(u.hash.slice(1));const text=fs.readFileSync(rel,'utf8');const escaped=id.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp('\\bid=["\\\']'+escaped+'["\\\']','i');if(!re.test(text))fragments.push({href:a.raw,target:rel,id})}}catch(e){broken.push({href:a.raw,error:String(e)})}}return{broken,fragments}}
(async()=>{
 const browser=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage','--autoplay-policy=user-gesture-required']});
 fs.mkdirSync('gate-a-final/full/screenshots',{recursive:true});
 for(const route of routes){out.cases[route]={};for(const vp of vps){const p=await browser.newPage();await p.setViewport({width:vp.width,height:vp.height,deviceScaleFactor:1});const consoleErrors=[],pageErrors=[],requestFailures=[];p.on('console',m=>{if(m.type()==='error')consoleErrors.push(m.text())});p.on('pageerror',e=>pageErrors.push(String(e)));p.on('requestfailed',r=>requestFailures.push({url:r.url(),error:r.failure()?.errorText||''}));let status=null;try{const res=await p.goto(base+route,{waitUntil:'load',timeout:30000});status=res?.status()??null;await p.evaluate(()=>document.fonts?.ready||Promise.resolve());await p.evaluate(async()=>{const h=Math.max(document.body.scrollHeight,document.documentElement.scrollHeight);for(let y=0;y<h;y+=Math.max(300,innerHeight*.7)){scrollTo(0,y);await new Promise(r=>setTimeout(r,25))}scrollTo(0,0);await new Promise(r=>setTimeout(r,100));const imgs=[...document.images];await Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{let done=false;const end=()=>{if(done)return;done=true;resolve()};img.addEventListener('load',end,{once:true});img.addEventListener('error',end,{once:true});setTimeout(end,2500)})));});await sleep(50);}catch(e){pageErrors.push(String(e))}
 const data=await p.evaluate(()=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const imgs=[...document.images].map(i=>({src:i.getAttribute('src')||'',complete:i.complete,naturalWidth:i.naturalWidth,naturalHeight:i.naturalHeight}));return{viewport:{w:innerWidth,h:innerHeight},scrollWidth:document.documentElement.scrollWidth,scrollHeight:document.documentElement.scrollHeight,horizontalOverflow:document.documentElement.scrollWidth>innerWidth+1,images:imgs,brokenImages:imgs.filter(i=>!i.complete||i.naturalWidth<1||i.naturalHeight<1),header:Boolean(document.querySelector('.site-header[data-header]')),footer:Boolean(document.querySelector('footer.site-footer')),main:Boolean(document.querySelector('main')),primaryNavLinks:document.querySelectorAll('#primary-nav a[href]').length,visibleActions:[...document.querySelectorAll('main a[href],main button,input[type="submit"]')].filter(vis).length,anchors:[...document.querySelectorAll('a[href]')].map(a=>({raw:a.getAttribute('href')||'',href:a.href,label:(a.textContent||'').trim()})),officialLegalName:(document.body.innerText||'').includes('UNIQE OTOMOTİV KİMYA SANAYİ LİMİTED ŞİRKETİ'),productStats:{core:document.querySelectorAll('[data-product-kind="core"]').length,inquiry:document.querySelectorAll('[data-product-kind="inquiry"]').length,uniqueInquiry:new Set([...document.querySelectorAll('[data-product-kind="inquiry"]')].map(x=>x.dataset.slug)).size}}});
 const linkAudit=localAudit(route,data.anchors);const row={status,...data,consoleErrors,pageErrors,requestFailures,linkAudit};out.cases[route][vp.name]=row;out.summary.cases++;if(row.horizontalOverflow)out.summary.horizontalOverflow++;out.summary.brokenImages+=row.brokenImages.length;out.summary.consoleErrors+=consoleErrors.length;out.summary.pageErrors+=pageErrors.length;out.summary.requestFailures+=requestFailures.length;if(!row.header||!row.footer||!row.main||row.primaryNavLinks!==6)out.summary.missingShell++;out.summary.brokenInternalLinks+=linkAudit.broken.length;out.summary.missingFragments+=linkAudit.fragments.length;if(businessRoutes.has(route)&&row.visibleActions<1)out.summary.missingActions++;if(!row.officialLegalName)out.summary.legalNameRegression++;
 if(![200,304].includes(status))out.failures.push({route,vp:vp.name,type:'status',detail:status});if(row.horizontalOverflow)out.failures.push({route,vp:vp.name,type:'horizontal-overflow',detail:{scrollWidth:row.scrollWidth,viewport:vp.width}});if(row.brokenImages.length)out.failures.push({route,vp:vp.name,type:'broken-images',detail:row.brokenImages});if(consoleErrors.length)out.failures.push({route,vp:vp.name,type:'console-errors',detail:consoleErrors});if(pageErrors.length)out.failures.push({route,vp:vp.name,type:'page-errors',detail:pageErrors});if(requestFailures.length)out.failures.push({route,vp:vp.name,type:'request-failures',detail:requestFailures});if(!row.header||!row.footer||!row.main||row.primaryNavLinks!==6)out.failures.push({route,vp:vp.name,type:'shell',detail:{header:row.header,footer:row.footer,main:row.main,links:row.primaryNavLinks}});if(linkAudit.broken.length)out.failures.push({route,vp:vp.name,type:'broken-internal-links',detail:linkAudit.broken});if(linkAudit.fragments.length)out.failures.push({route,vp:vp.name,type:'missing-fragments',detail:linkAudit.fragments});if(businessRoutes.has(route)&&row.visibleActions<1)out.failures.push({route,vp:vp.name,type:'missing-visible-action',detail:row.visibleActions});if(!row.officialLegalName)out.failures.push({route,vp:vp.name,type:'official-legal-name-regression'});if(route==='products.html'&&(row.productStats.core!==3||row.productStats.inquiry!==62||row.productStats.uniqueInquiry!==62))out.failures.push({route,vp:vp.name,type:'product-static-count-regression',detail:row.productStats});
 await p.screenshot({path:`gate-a-final/full/screenshots/${route.replace('.html','')}-${vp.name}.png`,fullPage:false});await p.close();}}
 fs.writeFileSync('gate-a-final/full/full-report.json',JSON.stringify(out,null,2));console.log(JSON.stringify({productSha:PRODUCT,summary:out.summary,failures:out.failures},null,2));await browser.close();if(out.summary.cases!==80||out.failures.length)process.exit(2);
})().catch(e=>{console.error(e);process.exit(1)});
